 FROM questions WHERE (id GLOB 'q_alevel_bio_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_chem_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_fm_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_math_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_phy_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_addmath_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_bio_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_chem_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_math_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_phy_[0-9][0-9][0-9]');CREATE TEMP TABLE _sf(c INTEGER,n INTEGER,a INTEGER,b INTEGER);INSERT INTO _sf(c,n,a,b) WITH RECURSIVE r(k,v) AS (SELECT row_number() OVER(ORDER BY id),json_array(id,subject_id,topic_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit) FROM (SELECT q.* FROM questions q JOIN _sr s ON s.id=q.id)),w(k,i,n,a,b,v) AS (SELECT k,0,length(v),7,11,v FROM r UNION ALL SELECT k,i+1,n,(a*131+unicode(substr(v,i+1,1)))%2147483647,(b*137+unicode(substr(v,i+1,1)))%2147483629,v FROM w WHERE i<n),f AS (SELECT k,n,a,b FROM w WHERE i=n) SELECT count(*) c,coalesce(sum(n),0) n,coalesce(sum((a*k)%2147483647)%2147483647,0) a,coalesce(sum((b*k)%2147483629)%2147483629,0) b FROM f;CREATE TEMP TABLE _tf(c INTEGER,n INTEGER,a INTEGER,b INTEGER);INSERT INTO _tf(c,n,a,b) WITH RECURSIVE r(k,v) AS (SELECT row_number() OVER(ORDER BY id),json_array(id,subject_id,parent_id,name,slug,description,theory_content,key_formulas,display_order,created_at) FROM topics WHERE id IN('topic_igcse_chem_electrolysis','topic_igcse_chem_analysis','topic_igcse_bio_cell_transport','topic_igcse_bio_excretion','topic_igcse_bio_coordination','topic_igcse_addmath_series','topic_alevel_phys_medical','topic_alevel_phys_particles','topic_alevel_bio_immunity','topic_alevel_math_diffeq','topic_alevel_fmath_summation','topic_alevel_fmath_induction','topic_alevel_fmath_polynomial_roots','topic_alevel_fmath_vectors','topic_alevel_fmath_integration')),w(k,i,n,a,b,v) AS (SELECT k,0,length(v),7,11,v FROM r UNION ALL SELECT k,i+1,n,(a*131+unicode(substr(